using NUnit.Framework;using UnityEngine;
namespace OneMoreTime.Tests {
public class MechanismTests {
 GameObject root;PlayerMotor2D player;PlayerTuning tuning;PressurePlate plate;EchoSurface echo;LinkedDoor door;
 [SetUp]public void Setup(){root=new GameObject("Mechanism fixture");tuning=ScriptableObject.CreateInstance<PlayerTuning>();var p=new GameObject("Player");p.transform.SetParent(root.transform);player=p.AddComponent<PlayerMotor2D>();player.tuning=tuning;player.worldMask=1<<31;player.Init();var floor=new GameObject("Ground");floor.transform.SetParent(root.transform);floor.layer=31;floor.transform.position=new Vector2(0,-1);floor.AddComponent<BoxCollider2D>().size=new Vector2(20,2);player.ResetAt(Vector2.zero);Physics2D.SyncTransforms();player.Step(default,.02f);var pg=new GameObject("Plate");pg.transform.SetParent(root.transform);plate=pg.AddComponent<PressurePlate>();var dg=new GameObject("Door");dg.transform.SetParent(root.transform);dg.transform.position=new Vector2(3,1);door=dg.AddComponent<LinkedDoor>();door.plate=plate;door.solid=dg.AddComponent<BoxCollider2D>();door.solid.size=new Vector2(1,2);var eg=new GameObject("Echo");eg.transform.SetParent(root.transform);echo=eg.AddComponent<EchoSurface>();var v=new GameObject("Visual");v.transform.SetParent(eg.transform);echo.visual=v.AddComponent<PlayerVisual>();echo.visual.library=ScriptableObject.CreateInstance<AnimationLibrary>();echo.visual.library.idle=new Sprite[1];echo.visual.renderer2D=v.AddComponent<SpriteRenderer>();var line=new GameObject("Line");line.transform.SetParent(eg.transform);echo.support=line.AddComponent<SpriteRenderer>();}
 [TearDown]public void Cleanup(){Object.DestroyImmediate(echo.visual.library);Object.DestroyImmediate(root);Object.DestroyImmediate(tuning);}
 [Test]public void LegalSourcesOnly(){var pose=new RecordedFrame{position=Vector2.zero,grounded=true};echo.Show(pose,true);plate.Evaluate(player,echo);Assert.AreEqual(2,plate.Sources);player.ResetAt(new Vector2(6,0));plate.Evaluate(player,echo);Assert.AreEqual(1,plate.Sources);echo.Show(pose,false);plate.Evaluate(player,echo);Assert.AreEqual(0,plate.Sources);pose.position=Vector2.up;echo.Show(pose,true);plate.Evaluate(player,echo);Assert.IsFalse(plate.Pressed);pose.position=Vector2.zero;pose.grounded=false;echo.Show(pose,true);plate.Evaluate(player,echo);Assert.IsFalse(plate.Pressed);}
 [Test]public void DoorProtectsOnlyActualOccupant(){echo.Clear();plate.Evaluate(player,echo);door.Evaluate(player);Assert.IsTrue(door.Open);player.ResetAt(new Vector2(3,0));plate.Evaluate(player,echo);door.Evaluate(player);Assert.IsTrue(door.Open);player.ResetAt(new Vector2(4,0));door.Evaluate(player);Assert.IsFalse(door.Open);door.ResetState();Assert.IsTrue(door.solid.enabled);}
 [Test]public void CrumbleIgnoresSideAndEcho(){var box=player.GroundCollider as BoxCollider2D;var c=box.gameObject.AddComponent<CrumblingPlatform>();c.solid=box;player.ResetAt(new Vector2(12,0));for(int i=0;i<100;i++)c.Tick(player,.02f);Assert.AreEqual(-1,c.Remaining);echo.Show(new RecordedFrame{position=Vector2.zero,grounded=true},true);for(int i=0;i<100;i++)c.Tick(player,.02f);Assert.AreEqual(-1,c.Remaining);Assert.IsFalse(c.Collapsed);}
 [Test]public void CrumbleTimerResetsWithoutOldCallbacks(){var solid=player.GroundCollider as BoxCollider2D;Assert.NotNull(solid);var c=solid.gameObject.AddComponent<CrumblingPlatform>();c.solid=solid;c.Tick(player,.02f);Assert.That(c.Remaining,Is.EqualTo(.63f).Within(.001));for(int i=0;i<30;i++)c.Tick(player,.02f);Assert.IsFalse(c.Collapsed);c.ResetState();player.ResetAt(new Vector2(0,5));for(int i=0;i<100;i++)c.Tick(player,.02f);Assert.IsFalse(c.Collapsed);player.ResetAt(Vector2.zero);Physics2D.SyncTransforms();player.Step(default,.02f);for(int i=0;i<34;i++)c.Tick(player,.02f);Assert.IsTrue(c.Collapsed);Assert.IsFalse(c.solid.enabled);c.ResetState();Assert.IsTrue(c.solid.enabled);}
}
}
